            {{- if index .Values "offload" "s3" "envSecrets" }}
              {{- range $key, $secret := $.Values.offload.s3.envSecrets }}
          - name: {{ $key }}
            valueFrom:
              secretKeyRef:
                name: {{ $secret }}
                key: {{ $key | quote }}
              {{- end }}
            {{- else if index .Values "backups" "s3" "envSecrets" }}
              {{- range $key, $secret := $.Values.backups.s3.envSecrets }}
          - name: {{ $key }}
            valueFrom:
              secretKeyRef:
                name: {{ $secret }}
                key: {{ $key | quote }}
              {{- end }}
            {{- else if index .Values "modules" "text2vec-aws" "envSecrets" }}
              {{- range $key, $secret := (index .Values "modules" "text2vec-aws" "envSecrets") }}
          - name: {{ $key }}
            valueFrom:
              secretKeyRef:
                name: {{ $secret }}
                key: {{ $key | quote }}
              {{- end }}
            {{- else if index .Values "modules" "generative-aws" "envSecrets" }}
              {{- range $key, $secret := (index .Values "modules" "generative-aws" "envSecrets") }}
          - name: {{ $key }}
            valueFrom:
              secretKeyRef:
                name: {{ $secret }}
                key: {{ $key | quote }}
              {{- end }}
            {{- end }}
            {{- if and (index .Values "backups" "s3" "secrets") (index .Values "backups" "s3" "secrets" "AWS_ACCESS_KEY_ID") }}
          - name: AWS_ACCESS_KEY_ID
            valueFrom:
              secretKeyRef:
                name: backup-s3
                key: AWS_ACCESS_KEY_ID
            {{- else if or (and (index .Values "offload" "s3" "secrets") (index .Values "offload" "s3" "secrets" "AWS_ACCESS_KEY_ID")) (and (index .Values "modules" "text2vec-aws" "secrets") (index .Values "modules" "text2vec-aws" "secrets" "AWS_ACCESS_KEY_ID")) (and (index .Values "modules" "multi2vec-aws" "secrets") (index .Values "modules" "multi2vec-aws" "secrets" "AWS_ACCESS_KEY_ID")) (and (index .Values "modules" "generative-aws" "secrets") (index .Values "modules" "generative-aws" "secrets" "AWS_ACCESS_KEY_ID")) }}
          - name: AWS_ACCESS_KEY_ID
            valueFrom:
              secretKeyRef:
                name: weaviate-aws
                key: AWS_ACCESS_KEY_ID
            {{- end }}
            {{- if and (index .Values "backups" "s3" "secrets") (index .Values "backups" "s3" "secrets" "AWS_SECRET_ACCESS_KEY") }}
          - name: AWS_SECRET_ACCESS_KEY
            valueFrom:
              secretKeyRef:
                name: backup-s3
                key: AWS_SECRET_ACCESS_KEY
            {{- else if or (and (index .Values "offload" "s3" "secrets") (index .Values "offload" "s3" "secrets" "AWS_SECRET_ACCESS_KEY")) (and (index .Values "modules" "text2vec-aws" "secrets") (index .Values "modules" "text2vec-aws" "secrets" "AWS_SECRET_ACCESS_KEY")) (and (index .Values "modules" "multi2vec-aws" "secrets") (index .Values "modules" "multi2vec-aws" "secrets" "AWS_SECRET_ACCESS_KEY")) (and (index .Values "modules" "generative-aws" "secrets") (index .Values "modules" "generative-aws" "secrets" "AWS_SECRET_ACCESS_KEY")) }}
          - name: AWS_SECRET_ACCESS_KEY
            valueFrom:
              secretKeyRef:
                name: weaviate-aws
                key: AWS_SECRET_ACCESS_KEY
            {{- end }}
          {{- end  }}
          {{- if index .Values "backups" "gcs" "enabled" }}
            {{- if index .Values "backups" "gcs" "envconfig" }}
              {{- range $key, $value := index .Values "backups" "gcs" "envconfig" }}
          - name: {{ $key }}
            value: {{ $value | quote }}
              {{- end }}
            {{- end }}
            {{- if or (index .Values "backups" "gcs" "secrets") (index .Values "backups" "gcs" "envSecrets") }}
              {{- if or (index .Values "backups" "gcs" "secrets" "GOOGLE_APPLICATION_CREDENTIALS") (index .Values "backups" "gcs" "envSecrets" "GOOGLE_APPLICATION_CREDENTIALS") }}
          - name: GOOGLE_APPLICATION_CREDENTIALS
            value: "/etc/gcp/credentials.json"
              {{- end }}
            {{- end }}
          {{- end  }}
          {{- if index .Values "backups" "azure" "enabled" }}
            {{- if index .Values "backups" "azure" "envconfig" }}
              {{- range $key, $value := index .Values "backups" "azure" "envconfig" }}
          - name: {{ $key }}
            value: {{ $value | quote }}
              {{- end }}
            {{- end }}
            {{- if index .Values "backups" "azure" "envSecrets" }}
              {{- range $key, $secret := $.Values.backups.azure.envSecrets }}
          - name: {{ $key }}
            valueFrom:
              secretKeyRef:
                name: {{ $secret }}
                key: {{ $key | quote }}
              {{- end }}
            {{- end }}
