          - name: AZURE_STORAGE_ACCOUNT
            valueFrom:
              secretKeyRef:
                name: backup-azure
                key: AZURE_STORAGE_ACCOUNT
            {{- end }}
            {{- if and (index .Values "backups" "azure" "secrets") (index .Values "backups" "azure" "secrets" "AZURE_STORAGE_KEY") }}
          - name: AZURE_STORAGE_KEY
            valueFrom:
              secretKeyRef:
                name: backup-azure
                key: AZURE_STORAGE_KEY
            {{- end }}
            {{- if and (index .Values "backups" "azure" "secrets") (index .Values "backups" "azure" "secrets" "AZURE_STORAGE_CONNECTION_STRING") }}
          - name: AZURE_STORAGE_CONNECTION_STRING
            valueFrom:
              secretKeyRef:
                name: backup-azure
                key: AZURE_STORAGE_CONNECTION_STRING
            {{- end }}
          {{- end  }}
          {{- if index .Values "usage" "gcs" "enabled" }}
            {{- if index .Values "usage" "gcs" "envconfig" }}
              {{- range $key, $value := index .Values "usage" "gcs" "envconfig" }}
          - name: {{ $key }}
            value: {{ $value | quote }}
              {{- end }}
            {{- end }}
          {{- end  }}
          {{- if index .Values "usage" "s3" "enabled" }}
            {{- if index .Values "usage" "s3" "envconfig" }}
              {{- range $key, $value := index .Values "usage" "s3" "envconfig" }}
          - name: {{ $key }}
            value: {{ $value | quote }}
              {{- end }}
            {{- end }}
          {{- end  }}
          {{- if .Values.mcp.enabled }}
