          - name: MCP_SERVER_CONFIG_PATH
            value: "/mcp-config/mcp-config.yaml"
          {{- end }}
          {{- end }}
          {{- if index .Values "collectionExport" "enabled" }}
          - name: EXPORT_ENABLED
            value: "true"
            {{- if index .Values "collectionExport" "envconfig" }}
              {{- range $key, $value := index .Values "collectionExport" "envconfig" }}
          - name: {{ $key }}
            value: {{ $value | quote }}
              {{- end }}
            {{- end }}
          {{- end }}
          {{- if index .Values "namespaces" "enabled" }}
          - name: NAMESPACES_ENABLED
            value: "true"
          - name: DISABLE_GRAPHQL
            value: "true"
          - name: REPLICATION_MAXIMUM_FACTOR
            value: "1"
          {{- end }}
          - name: CLUSTER_JOIN
            value: {{ .Values.service.name }}-headless.{{ .Release.Namespace }}.svc.{{ .Values.clusterDomain }}
        ports:
          - containerPort: 8080
          {{- if .Values.env.PROMETHEUS_MONITORING_ENABLED }}
          - name: metrics
            containerPort: 2112
            protocol: TCP
          {{- end }}
          {{ if .Values.grpcService.enabled }}
          - name: grpc
            containerPort: 50051
            protocol: TCP
          {{- end }}
        volumeMounts:
          - name: weaviate-config
            mountPath: /weaviate-config
          - name: {{ .Values.storage.name }}
            mountPath: /var/lib/weaviate
          {{- if .Values.runtime_overrides.enabled }}
          - name: weaviate-runtime-overrides
            mountPath: /config
          {{- end }}
          {{- if and .Values.mcp.enabled .Values.mcp.config }}
          - name: weaviate-mcp-config
            mountPath: /mcp-config
          {{- end }}
          {{- if index .Values "backups" "gcs" "enabled" }}
            {{- if or (index .Values "backups" "gcs" "secrets") (index .Values "backups" "gcs" "envSecrets") }}
              {{- if or (index .Values "backups" "gcs" "secrets" "GOOGLE_APPLICATION_CREDENTIALS") (index .Values "backups" "gcs" "envSecrets" "GOOGLE_APPLICATION_CREDENTIALS") }}
          - name: gcs-service-account-credentials-volume
            mountPath: /etc/gcp
            readOnly: true
              {{- end }}
            {{- end }}
          {{- end }}
          {{ with .Values.extraVolumeMounts }}
            {{ toYaml . | nindent 10 }}
          {{- end }}
        {{- if .Values.startupProbe.enabled }}
        startupProbe:
          {{- $probeType := .Values.startupProbe.probeType }}
          {{- $probe := index .Values.startupProbe.probe $probeType }}
          {{ $probeType }}:
            {{- toYaml $probe | nindent 12 }}
          initialDelaySeconds: {{ .Values.startupProbe.initialDelaySeconds }}
          periodSeconds: {{ .Values.startupProbe.periodSeconds }}
          failureThreshold: {{ .Values.startupProbe.failureThreshold }}
          successThreshold: {{ .Values.startupProbe.successThreshold }}
          timeoutSeconds: {{ .Values.startupProbe.timeoutSeconds }}
        {{- end }}
        livenessProbe:
          {{- $probeType := .Values.livenessProbe.probeType }}
          {{- $probe := index .Values.livenessProbe.probe $probeType }}
          {{ $probeType }}:
            {{- toYaml $probe | nindent 12 }}
          initialDelaySeconds: {{ .Values.livenessProbe.initialDelaySeconds }}
          periodSeconds: {{ .Values.livenessProbe.periodSeconds }}
          failureThreshold: {{ .Values.livenessProbe.failureThreshold }}
          successThreshold: {{ .Values.livenessProbe.successThreshold }}
          timeoutSeconds: {{ .Values.livenessProbe.timeoutSeconds }}
        readinessProbe:
          {{- $probeType := .Values.readinessProbe.probeType }}
          {{- $probe := index .Values.readinessProbe.probe $probeType }}
          {{ $probeType }}:
            {{- toYaml $probe | nindent 12 }}
          initialDelaySeconds: {{ .Values.readinessProbe.initialDelaySeconds }}
          periodSeconds: {{ .Values.readinessProbe.periodSeconds }}
          failureThreshold: {{ .Values.readinessProbe.failureThreshold }}
          successThreshold: {{ .Values.readinessProbe.successThreshold }}
          timeoutSeconds: {{ .Values.readinessProbe.timeoutSeconds }}
        securityContext:
{{ toYaml .Values.containerSecurityContext | indent 10}}
      volumes:
        {{- if .Values.runtime_overrides.enabled }}
        - name: weaviate-runtime-overrides
          configMap:
            name: weaviate-runtime-overrides
        {{- end }}
        {{- if and .Values.mcp.enabled .Values.mcp.config }}
        - name: weaviate-mcp-config
          configMap:
            name: weaviate-mcp-config
        {{- end }}
        - name: weaviate-config
          configMap:
